const year = new Date().getUTCFullYear();
const emailTo = 'dbertona@powersolution.es';

let mode = 'full';
try {
  if ($('Schedule salud 2h').isExecuted) mode = 'pipeline';
} catch (_) {}
try {
  const wh = $('Webhook manual').first()?.json || {};
  const body = wh.body || wh;
  const q = wh.query || {};
  const m = String(body.mode || q.mode || '').toLowerCase().trim();
  if (['pipeline', 'salud', 'health'].includes(m)) mode = 'pipeline';
  if (['full', 'completo', 'bc'].includes(m)) mode = 'full';
} catch (_) {}

const companies = [
  { slug: 'psi', companyName: 'Power Solution Iberia SL', companyId: 'ca9dc1bf-54ee-ed11-884a-000d3a455d5b' },
  { slug: 'pslab', companyName: 'PS LAB CONSULTING SL', companyId: '656f8f0e-2bf4-ed11-8848-000d3a4baf18' },
];
return companies.map(c => ({ json: { ...c, year, emailTo, mode } }));

const year = Number($json.year);
const companyName = $json.companyName;
const companyId = $json.companyId;
const env = (($env.BC_ENVIRONMENT && String($env.BC_ENVIRONMENT).trim()) || 'Production');
const base = 'https://api.businesscentral.dynamics.com/v2.0/a18dc497-a8b8-4740-b723-65362ab7a3fb/'
  + env + '/api/Power_Solution/PS_API/v2.0/companies(' + companyId + ')';

const movUrl = base + "/movimientosProyectosMes"
  + "?$select=invoice,cost,year,descripcionCA,job"
  + "&$filter=year%20eq%20'" + year + "'%20and%20descripcionCA%20eq%20'Ingresos'";

const movCostUrl = base + "/movimientosProyectosMes"
  + "?$select=job,cost,year,descripcionCA"
  + "&$filter=year%20eq%20'" + year + "'";

const certUrl = base + "/movimientosProyectos"
  + "?$select=jobNo,year,month,totalPrice,descripcion,tieneCertificacion,documentNo,no"
  + "&$filter=year%20eq%20'" + year + "'%20and%20descripcion%20eq%20'Ingresos'%20and%20tieneCertificacion%20eq%20true";

const planifUrl = base + "/planificacionMes"
  + "?$select=job,year,month,invoice,cost,nr,estado,budgetDateYear,budgetDateMonth,descripcionCA"
  + "&$filter=year%20eq%20" + year;

const expedienteUrl = base + "/expedienteMes"
