const diasCountUrl = base + "/diasdeImputacion/$count";
const proyectosCountUrl = base + "/proyectos/$count";
const recursosCountUrl = base + "/Recursos/$count";
const lineCountUrl = base + "/movimientosProyectos/$count"
  + "?$filter=year%20eq%20'" + year + "'";

return [{ json: {
  year, companyName, companyId, slug: $json.slug,
  movUrl, movCostUrl, certUrl, planifUrl, expedienteUrl, cerradosUrl,
  historicoUrl, diasCountUrl, proyectosCountUrl, recursosCountUrl, lineCountUrl,
  emailTo: $json.emailTo || 'dbertona@powersolution.es',
