}}];

const input = $input.all();
const meta = $('Build BC URLs').first().json;
let sum = 0;
let count = 0;
const byJob = {};
const add = (job, inv) => {
  const j = String(job || '').trim();
  if (!j || j.startsWith('PP') || j.startsWith('PY')) return;
  byJob[j] = Number(((byJob[j] || 0) + Math.abs(inv)).toFixed(2));
};
for (const it of input) {
  const raw = it?.json ?? {};
  if (raw.error || raw.statusCode >= 400) continue;
  const src = raw?.body ?? raw;
  const chunk = Array.isArray(src.value) ? src.value : (Array.isArray(src) ? src : []);
  for (const r of chunk) {
    const inv = Number(r.invoice ?? 0);
    if (!Number.isFinite(inv)) continue;
    sum += inv;
    count += 1;
    add(r.job, inv);
  }
}
return [{ json: {
  ...meta,
  bc_r_mov_sum: Math.abs(sum),
  bc_r_sum: Math.abs(sum),
  bc_r_count: count,
  bc_r_mov_by_job: byJob,
}}];

const input = $input.all();
const meta = $('Sum Movimientos BC').first().json;
const allowed = new Set(['Planning', 'Quote', 'Open', 'Completed', 'Lost']);
const toNum = (v) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};
let sum = 0;
let costSum = 0;
let count = 0;
let bcOk = false;
const bcPlanifKeys = [];
const keySeen = new Set();
const byJob = {};
const costByJob = {};
for (const it of input) {
  const raw = it?.json ?? {};
  if (raw.error || raw.statusCode >= 400) continue;
  bcOk = true;
  const src = raw?.body ?? raw;
  const chunk = Array.isArray(src.value) ? src.value : (Array.isArray(src) ? src : []);
  for (const r of chunk) {
    const job = String(r.job ?? '').trim();
    if (!job || job.startsWith('PP') || job.startsWith('PY')) continue;
    const status = String(r.estado ?? r.status ?? '').trim();
    if (!allowed.has(status)) continue;
    const year = Number(r.year ?? 0) || 0;
    const month = Number(r.month ?? 0) || 0;
    if (!year || !month) continue;
    const budgetYear = toNum(r.budgetDateYear);
    const budgetMonth = toNum(r.budgetDateMonth);
    if (budgetYear !== 0 && (year !== budgetYear || month < budgetMonth)) continue;
    const inv = toNum(r.invoice);
    const cost = toNum(r.cost);
    sum += inv;
    costSum += cost;
    count += 1;
    byJob[job] = Number(((byJob[job] || 0) + inv).toFixed(2));
    costByJob[job] = Number(((costByJob[job] || 0) + cost).toFixed(2));
    const nr = String(r.nr ?? r.lineNo ?? r.line_no ?? '').trim();
    if (!nr) continue;
    const key = job + '|' + nr + '|' + year + '|' + month;
    if (keySeen.has(key)) continue;
    keySeen.add(key);
    bcPlanifKeys.push(key);
  }
}
return [{ json: {
  ...meta,
  bc_p_planif_sum: Number(sum.toFixed(2)),
  bc_p_planif_count: count,
  bc_p_cost_sum: Number(costSum.toFixed(2)),
  bc_planif_ok: bcOk,
  bcPlanifKeys,
  bc_p_planif_by_job: byJob,
  bc_p_cost_by_job: costByJob,
}}];

const input = $input.all();
const meta = $('Sum Planificacion BC').first().json;
const toNum = (v) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};
let sum = 0;
let count = 0;
let bcOk = false;
const bcExpedienteKeys = [];
const keySeen = new Set();
const byJob = {};
for (const it of input) {
  const raw = it?.json ?? {};
  if (raw.error || raw.statusCode >= 400) continue;
  bcOk = true;
  const src = raw?.body ?? raw;
  const chunk = Array.isArray(src.value) ? src.value : (Array.isArray(src) ? src : []);
  for (const r of chunk) {
    const job = String(r.job ?? '').trim();
    if (!job || job.startsWith('PP') || job.startsWith('PY')) continue;
    const status1 = String(r.status1 ?? r.monthClosingStatus ?? '').trim();
    if (status1 === 'Completed' || status1 === 'Lost') continue;
    const year = Number(r.year ?? 0) || 0;
