    const unit = String(r.jobUnitNo ?? r.job_unit_no ?? '').trim();
    const key = job + '|' + unit + '|' + year + '|' + month;
    if (keySeen.has(key)) continue;
    keySeen.add(key);
    bcExpedienteKeys.push(key);
  }
}
return [{ json: {
  ...meta,
  bc_p_expediente_sum: Number(sum.toFixed(2)),
  bc_p_expediente_count: count,
  bc_expediente_ok: bcOk,
