const bcByMonth = meta.bc_cerrados_by_month || {};
const months = new Set([...Object.keys(bcByMonth), ...Object.keys(anByMonth)]);
for (const ym of [...months].sort()) {
  const bcM = num(bcByMonth[ym]);
  const anM = num(anByMonth[ym]);
  if (!bcM && !anM) continue;
  push('meses_cerrados_' + ym.replace('-', '_'), bcM, anM, 50, 'cerrados_month', { year_month: ym });
}

function collect004EntityErrors(raw) {
  let list = raw;
  if (typeof list === 'string') {
    try { list = JSON.parse(list); } catch (_) { list = []; }
  }
  if (list && !Array.isArray(list) && typeof list === 'object') list = [list];
  if (!Array.isArray(list)) list = [];
  const errors = [];
  for (const row of list) {
    if (!row) continue;
    let sync = row.sync_details;
    if (typeof sync === 'string') {
      try { sync = JSON.parse(sync); } catch (_) { sync = {}; }
    }
    const before = errors.length;
    if (sync && typeof sync === 'object') {
      for (const [key, v] of Object.entries(sync)) {
        if (!v || typeof v !== 'object') continue;
        const st = String(v.status || '');
        const msg = String(v.message || '');
        if ((st && st !== 'ok' && st !== 'skipped') || /invalid syntax/i.test(msg)) {
          errors.push({ entity: key, status: st || 'error', message: msg || st, exec: row.id });
        }
      }
    }
    if (errors.length === before && (row.status === 'error' || row.status === 'partial_error')) {
      errors.push({ entity: '*', status: row.status, message: '004 status ' + row.status, exec: row.id });
    }
  }
  return errors;
}
const entityErrors = collect004EntityErrors(a.last_004);
push('sync_004_entity_errors', 0, entityErrors.length, 0, 'signal', {
  sample: entityErrors.slice(0, 8),
});

push('budget0_past_with_invoice', 0, an_budget0, 0, 'signal');

const bcKeys = new Set(Array.isArray(meta.bcPlanifKeys) ? meta.bcPlanifKeys : []);
let anKeys = a.planif_keys;
if (typeof anKeys === 'string') {
