    note: 'BC ExpedienteMes HTTP failed; skip orphan check',
  });
}


function parseMap(raw) {
  let m = raw;
  if (typeof m === 'string') {
    try { m = JSON.parse(m); } catch (_) { m = {}; }
  }
  if (!m || typeof m !== 'object' || Array.isArray(m)) m = {};
  const out = {};
  for (const [k, v] of Object.entries(m)) {
    const key = String(k || '').trim();
    if (!key || key.startsWith('PP') || key.startsWith('PY')) continue;
    const n = Number(v);
    out[key] = Number.isFinite(n) ? n : 0;
  }
  return out;
}

function pushJobDiff(checkName, bcMap, anMap, tolFail = 1) {
  const keys = new Set([...Object.keys(bcMap), ...Object.keys(anMap)]);
  const mismatches = [];
  for (const job of keys) {
    const bc = num(bcMap[job]);
    const an = num(anMap[job]);
    const delta = Number((bc - an).toFixed(2));
    if (Math.abs(delta) <= 0.009) continue;
    const st = Math.abs(delta) > tolFail ? 'fail' : 'warn';
    mismatches.push({ job, bc, an, delta, status: st });
  }
  mismatches.sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta));
  const failCount = mismatches.filter((x) => x.status === 'fail').length;
  const warnCount = mismatches.filter((x) => x.status === 'warn').length;
  push(checkName, 0, failCount, 0, 'signal', {
    warn_count: warnCount,
    mismatch_count: mismatches.length,
    sample: mismatches.slice(0, 50),
    bc_jobs: Object.keys(bcMap).length,
    an_jobs: Object.keys(anMap).length,
  });
}

const bcRByJob = parseMap(meta.bc_r_by_job);
