}

push('v_se_coste_r', Number(num(a.r_cost_sum).toFixed(2)), Number(num(a.v_se_coste_r).toFixed(2)), 0.5, 'abs');
push('v_se_coste_p', Number(num(a.p_cost_sum).toFixed(2)), Number(num(a.v_se_coste_p).toFixed(2)), 0.5, 'abs');

if (meta.bc_historico_ok) {
  push(
    'historico_planif_sum',
    Number(num(meta.bc_historico_sum).toFixed(2)),
    Number(num(a.historico_sum).toFixed(2)),
    0.5,
    'abs',
    { bc_count: meta.bc_historico_count, an_count: a.historico_count }
  );
