function readCount(items) {
  let ok = false;
  let n = 0;
  for (const it of items) {
    const raw = it?.json ?? {};
    if (raw.error || raw.statusCode >= 400) continue;
    ok = true;
    const src = raw?.body ?? raw?.data ?? raw;
    if (typeof src === 'number') { n = src; break; }
    if (typeof src === 'string' && src.trim() !== '' && !Number.isNaN(Number(src))) { n = Number(src); break; }
    if (src && typeof src === 'object') {
      if (typeof src['@odata.count'] === 'number') { n = src['@odata.count']; break; }
      if (typeof src.value === 'number') { n = src.value; break; }
      if (typeof src === 'object' && raw.statusCode) {
        // some gateways put body as raw string already parsed
      }
    }
  }
  return { ok, n: Number(n) || 0 };
}

